<template><section class="pre-archive-matrix"><div class="matrix-selectors"><details><summary>颜色：{{colors.join('、')||'请选择'}}</summary><label v-for="c in orderColorOptions" :key="c"><input type="checkbox" :checked="colors.includes(c)" @change="toggleColor(c)"/>{{c}}</label></details><details><summary>尺码：{{sizes.join('、')||'请选择'}}</summary><label v-for="s in sizeOptions" :key="s"><input type="checkbox" :checked="sizes.includes(s)" @change="toggleSize(s)"/>{{s}}</label></details><select aria-label="样衣尺码模板" @change="template($event)"><option value="">选择尺码模板</option><option v-for="t in templates" :value="t.id" :key="t.id">{{t.name}}</option></select><input v-model="customSize" maxlength="50" placeholder="自定义尺码"/><button type="button" @click="addCustom">增加尺码</button></div><div class="matrix-main"><aside><img v-if="item.effect_image_url" :src="item.effect_image_url" @click="openImage(item.effect_image_url,item.style_no)"/><b>{{item.style_no}}</b><small>{{item.product_name}}</small></aside><div class="matrix-scroll"><table><thead><tr><th>颜色 / 尺码</th><th v-for="s in sizes" :key="s">{{s}}</th><th>合计</th></tr></thead><tbody><tr class="customer-size-row"><th>客户尺码</th><td v-for="s in sizes" :key="s"><input :aria-label="s+'客户尺码'" :value="rows.find(r=>r.size===s)?.customer_size||''" maxlength="50" placeholder="客户尺码" @input="setCustomerSize(s,$event.target.value)"/></td><td></td></tr><tr v-for="c in colors" :key="c"><td>{{c||'待确认'}}</td><td v-for="s in sizes" :key="s"><input :aria-label="c+' '+s+'数量'" type="number" min="0" max="1000000" step="1" :value="cell(c,s)?.qty||0" @input="setQty(c,s,$event.target.value)"/><label v-if="splitPrice">USD <input type="number" min="0" step="0.01" :value="cell(c,s)?.unit_price||0" @input="setPrice(c,s,$event.target.value)"/></label></td><td class="matrix-total">{{sum(c)}}</td></tr><tr><th>合计</th><td v-for="s in sizes" :key="s" class="matrix-total">{{rows.filter(r=>r.size===s).reduce((n,r)=>n+Number(r.qty||0),0)}}</td><td class="matrix-total">{{totalQty}}</td></tr></tbody></table><p v-if="!sizes.length">请选择尺码或尺码模板后填写数量。</p></div></div><footer><label><input type="checkbox" v-model="splitPrice" @change="changePricingMode"/>分颜色尺码单价</label><label v-if="!splitPrice">销售单价 USD <input type="number" min="0" step="0.01" :value="rows[0]?.unit_price||0" @input="uniformPrice($event.target.value)"/></label><span>下单数量 {{totalQty}}　商品金额 USD {{amount.toFixed(2)}}</span><button type="button" class="danger" @click="$emit('remove')">删除商品</button></footer></section></template>
<script setup>
import {computed,ref} from 'vue';import {orderColorOptions} from '../utils/orderOptions';import {openImage} from '../store/viewer';
const props=defineProps({item:Object,templates:Array});defineEmits(['remove']);const customSize=ref(''),extraSizes=ref([]),splitPrice=ref(new Set((props.item.size_prices||[]).map(r=>r.unit_price)).size>1);const rows=computed(()=>props.item.size_prices||[]),colors=computed(()=>[...new Set(rows.value.map(r=>r.color||''))]),sizes=computed(()=>[...new Set(rows.value.map(r=>r.size))]),sizeOptions=computed(()=>[...new Set(['NB','0-3M','3-6M','6-12M','12-18M','18-24M','2T','3T','4T','5-6T','6-7T','7-8T','8-9T','9-10T','10-12T','12-14T','14-16T','16T','XS','S','M','L','XL','2XL','3XL','4XL','5XL',...extraSizes.value,...sizes.value])]);
const cell=(c,s)=>rows.value.find(r=>(r.color||'')===c&&r.size===s);const totalQty=computed(()=>rows.value.reduce((n,r)=>n+Number(r.qty||0),0));const amount=computed(()=>rows.value.reduce((n,r)=>n+Math.round(Number(r.qty||0)*Math.round(Number(r.unit_price||0)*100)),0)/100);const sum=c=>rows.value.filter(r=>(r.color||'')===c).reduce((n,r)=>n+Number(r.qty||0),0);
function changePricingMode(){if(!splitPrice.value&&new Set(rows.value.map(r=>Number(r.unit_price||0))).size>1){splitPrice.value=true;alert('当前颜色尺码单价不同，请核对单价一致后再关闭分价。');}}
function setCustomerSize(size,value){rows.value.filter(r=>r.size===size).forEach(r=>r.customer_size=value);}
function sync(){props.item.expected_qty=totalQty.value;}
function addCells(cs,ss){const additions=cs.flatMap(color=>ss.filter(size=>!cell(color,size)).map(size=>({color,size,customer_size:rows.value.find(r=>r.size===size)?.customer_size||'',qty:0,unit_price:splitPrice.value?0:rows.value[0]?.unit_price||0})));props.item.size_prices.push(...additions);sync();}
function toggleColor(c){if(colors.value.includes(c)){props.item.size_prices=rows.value.filter(r=>(r.color||'')!==c);sync();}else addCells([c],sizes.value.length?sizes.value:['M']);}
function toggleSize(s){if(sizes.value.includes(s)){props.item.size_prices=rows.value.filter(r=>r.size!==s);sync();}else addCells(colors.value.length?colors.value:['印花001'],[s]);}
function setQty(c,s,v){cell(c,s).qty=v===''?0:Number(v);sync();}function setPrice(c,s,v){cell(c,s).unit_price=v===''?0:Number(v);}function uniformPrice(v){const price=v===''?0:Number(v);rows.value.forEach(r=>r.unit_price=price);}
function template(e){const t=props.templates.find(t=>String(t.id)===e.target.value);if(!t)return;const ss=Array.isArray(t.sizes)?t.sizes.map(s=>typeof s==='string'?s:s.size||s.name):String(t.sizes||'').split(/[,，]/);addCells(colors.value.length?colors.value:['印花001'],ss.map(s=>s.trim()).filter(Boolean));e.target.value='';}
function addCustom(){const s=customSize.value.trim();if(!s)return;extraSizes.value.push(s);addCells(colors.value.length?colors.value:['印花001'],[s]);customSize.value='';}
</script><style scoped>.pre-archive-matrix{background:var(--surface);border:1px solid var(--line);padding:16px;margin:12px 0}.matrix-selectors{display:flex;gap:12px;align-items:flex-start;flex-wrap:wrap}.matrix-selectors details{position:relative;border:1px solid var(--line);padding:8px;max-width:340px}.matrix-selectors details label{display:inline-flex;font-size:12px;margin:5px}.matrix-selectors summary{cursor:pointer;font-size:12px}.matrix-selectors input,.matrix-selectors select,footer input{border:1px solid var(--line);padding:5px;background:var(--surface);color:var(--ink)}.matrix-main{display:flex;gap:20px;margin:20px 0}.matrix-main aside{width:140px;flex:none;display:flex;align-items:center;flex-direction:column;gap:12px;text-align:center}.matrix-main img{width:110px;height:120px;object-fit:contain;border:1px solid var(--line);cursor:zoom-in}.matrix-main small{color:var(--ink-mute)}.matrix-scroll{overflow:auto;flex:1}table{border-collapse:collapse;width:100%;font-size:12px}th,td{border:1px solid var(--line);padding:8px;text-align:center;min-width:85px}th{background:var(--surface-2)}td>input,td label input{width:65px;border:1px solid var(--line);background:var(--surface);color:var(--ink);padding:3px;text-align:center}td label{display:block;margin-top:5px;font-size:10px}.matrix-total{color:#1890ff}footer{display:flex;gap:20px;align-items:center;justify-content:flex-end;font-size:12px;flex-wrap:wrap}footer input[type=number]{width:85px}.danger{color:var(--danger)}</style>
